// spec: .qa/e2e/specs/registration.md
// seed: tests/seed.spec.ts
import { test, expect } from '@playwright/test';

test.describe('Регистрация', () => {
  test('RG-01 «הצטרפו אלינו» на /phone открывает регистрацию #6a967a00 @prod-safe', async ({ page }) => {
    // 1. Открыть `/` → «בואו נתחיל» → `/phone`.
    await page.goto('/');
    await page.getByRole('button', { name: 'בואו נתחיל' }).click();
    await expect(page).toHaveURL(/\/phone$/);

    // 2. Нажать «הצטרפו אלינו».
    await page.getByRole('link', { name: 'הצטרפו אלינו' }).click();
    await expect(page).toHaveURL(/\/register$/);
    await expect(page.getByRole('heading', { level: 1, name: 'יצירת חשבון' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'שם מלא *' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'אימייל *' })).toBeVisible();
    await expect(page.getByRole('textbox', { name: 'מספר טלפון *' })).toBeVisible();
    await expect(page.getByRole('checkbox', { name: 'אני מאשר את תנאי השימוש ואת מדיניות הפרטיות' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'שלח' })).toBeVisible();
    // Это не экран входа.
    await expect(page.getByRole('heading', { name: 'כניסה דרך מספר נייד' })).toHaveCount(0);
  });
});
